In the diagram, the perimeter of the rectangle is 56. What is its area?

[asy]
unitsize(1inch);

pair A, B,C,D;
A =(0,0);
B= (1,0);
D = (0,0.8);
C = B+D;
draw(A--B--C--D--A);
label("$x+2$",B/2,S);
label("$x-2$",D/2,W);
[/asy]

```python
from sympy import symbols, solve, simplify

def rectangle_area():
    """In the diagram, the perimeter of the rectangle is 56. What is its area?

[asy]
unitsize(1inch);

pair A, B,C,D;
A =(0,0);
B= (1,0);
D = (0,0.8);
C = B+D;
draw(A--B--C--D--A);
label("$x+2$",B/2,S);
label("$x-2$",D/2,W);
[/asy]"""
    x = symbols('x')
    # The perimeter of a rectangle is 2*(length + width)
    # Given that the perimeter is 56, we can set up the equation 2*(x + 2) + 2*(x - 2) = 56
    equation = 2*(x + 2) + 2*(x - 2) - 56
    # Solve the equation for x
    solution = solve(equation, x)
    # The area of a rectangle is length * width
    area = (solution[0] + 2) * (solution[0] - 2)
    # Simplify the area
    area = simplify(area)

    return area

result = rectangle_area()
print(result)
```

