[/asy]

```python
from sympy import symbols, solve, sqrt

def find_k():
    """Two circles are centered at the origin, as shown.  The point $P(8,6)$ is on the larger circle and the point $S(0,k)$ is on the smaller circle.  If $QR=3$, what is the value of $k$? [asy]
defaultpen(linewidth(.7pt)+fontsize(10pt));
dotfactor=4;
draw(Circle((0,0),7)); draw(Circle((0,0),10));
dot((0,0)); dot((7,0)); dot((10,0)); dot((0,7)); dot((8,6));
draw((0,0)--(8,6));
label("$S (0,k)$",(0,7.5),W);
draw((13,0)--(0,0)--(0,13),Arrows(TeXHead));
draw((-13,0)--(0,0)--(0,-13));

label("$x$",(13,0),E); label("$y$",(0,13),N); label("$P(8,6)$",(8,6),NE);

label("$O$",(0,0),SW); label("$Q$",(7,0),SW); label("$R$",(10,0),SE);

[/asy]"""
    k = symbols('k')

    # The distance from the origin to the center of the larger circle is 10
    # The distance from the origin to the center of the smaller circle is 7
    # The distance from the center of the larger circle to P is 8
    # The distance from the center of the smaller circle to S is k

    # Using the Pythagorean theorem, we can set up the following equation:
    # (10 - 8)**2 + 6**2 = 7**2 + k**2
    equation = (10 - 8)**2 + 6**2 - 7**2 - k**2

    # Solve the equation for k
    solution = solve(equation, k)

    return solution[0]

result = find_k()
print(result)
```

