from sympy import symbols, Rational, simplify

def operation_value():
    """Each of the symbols $\star$ and $*$ represents an operation in the set $\{+,-,\times,\div\}$, and $\frac{12\star 2}{9*3}=4$.  What is the value of $\frac{10\star 7}{24*9}$?  Express your answer as a common fraction."""
    x, y = symbols('x y')

    operations = {
        '+': lambda x, y: x + y,
        '-': lambda x, y: x - y,
        '*': lambda x, y: x * y,
        '/': lambda x, y: x / y,
    }

    for star_op in operations.values():
        for mul_op in operations.values():
            if abs(star_op(12, 2) / mul_op(9, 3) - 4) < 1e-6:  # close to 4
                return Rational(star_op(10, 7), mul_op(24, 9))

    return None

result = operation_value()
print(result)
```

